const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Somalia';
  const geometry = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
                     .filter(ee.Filter.eq('country_na', countryName))
                     .geometry();

  const targetYear = 2019;
  const targetMonth = 4;
  const baselineStartYear = 2002;
  const baselineEndYear = 2018;

  const startDateTarget = ee.Date.fromYMD(targetYear, targetMonth, 1);
  const endDateTarget = startDateTarget.advance(1, 'month');

  // 2. Data Acquisition
  const dataset = ee.ImageCollection('NASA/FLDAS/NOAH01/C/GL/M/V001');
  const soilMoistureBand = 'SoilMoi00_10cm_tavg';

  // Target period (April 2019)
  const targetCollection = dataset.filterDate(startDateTarget, endDateTarget)
                                  .select(soilMoistureBand);

  // Baseline period (All Aprils from 2002-2018)
  const baselineCollection = dataset.filter(ee.Filter.calendarRange(baselineStartYear, baselineEndYear, 'year'))
                                    .filter(ee.Filter.calendarRange(targetMonth, targetMonth, 'month'))
                                    .select(soilMoistureBand);

  // 3. Data Availability Check
  const targetSize = targetCollection.size().getInfo();
  const baselineSize = baselineCollection.size().getInfo();

  console.log(`Images for April 2019: ${targetSize}`);
  console.log(`Images for baseline (Aprils ${baselineStartYear}-${baselineEndYear}): ${baselineSize}`);

  if (targetSize === 0 || baselineSize === 0) {
    console.log("Evidence: One or both image collections are empty.");
    console.log("A: C1");
    return;
  }

  // 4. Processing & Calculation
  const targetImage = targetCollection.mean().clip(geometry);
  const baselineImage = baselineCollection.mean().clip(geometry);

  const scale = 5000; // Use a coarse scale appropriate for the dataset and large geometry

  const reducers = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const targetStats = targetImage.reduceRegion({
    reducer: reducers,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const baselineStats = baselineImage.reduceRegion({
    reducer: reducers,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const targetVal = targetStats.get(soilMoistureBand + '_mean').getInfo();
  const targetPixels = targetStats.get(soilMoistureBand + '_count').getInfo();

  const baselineVal = baselineStats.get(soilMoistureBand + '_mean').getInfo();
  const baselinePixels = baselineStats.get(soilMoistureBand + '_count').getInfo();

  // 5. Validation & Final Answer
  console.log(`April 2019 Avg Soil Moisture (kg/m^2): ${targetVal ? targetVal.toFixed(2) : 'N/A'}`);
  console.log(`April 2019 Valid Pixels: ${targetPixels}`);
  console.log(`Baseline (${baselineStartYear}-${baselineEndYear}) Avg Soil Moisture (kg/m^2): ${baselineVal ? baselineVal.toFixed(2) : 'N/A'}`);
  console.log(`Baseline Valid Pixels: ${baselinePixels}`);

  if (targetPixels === 0 || baselinePixels === 0) {
    console.log("Evidence: No valid pixels found after processing for one or both periods.");
    console.log("A: C2");
    return;
  }

  if (targetVal === null || baselineVal === null) {
    console.log("Evidence: Calculation returned a null value.");
    console.log("A: C3");
    return;
  }

  if (targetVal < baselineVal) {
    console.log("A: A");
  } else {
    console.log("A: B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("Error running analysis: ", err);
    console.log("A: D");
});
